insert into wakilisha_repaired.content_route_classification (legacy_wp_post_id, legacy_post_type, slug, title, classification, react_route, migration_action, needs_review, review_reason, source_payload) values
  ('82cd52d0-7e0e-4708-b975-dd9584fb5f38', 'post', 'our-business', 'OUR BUSINESS', 'article', null, 'review_or_retire', true, 'article_not_published', '{"id":"82cd52d0-7e0e-4708-b975-dd9584fb5f38","source_wp_post_id":"21928","document_type":"page","slug":"our-business","title":"OUR BUSINESS","wp_status":"draft","content_html":"<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"canvasClassName\":\"cnvs-block-core-heading-1611676855242\"} -->\n<h3 class=\"has-text-align-center\"><strong>OUR PURPOSE</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:canvas/section {\"canvasClassName\":\"cnvs-block-section-1611676898720\",\"canvasLocation\":\"root\",\"layout\":\"full\"} -->\n<!-- wp:canvas/section-content {\"canvasClassName\":\"cnvs-block-section-content-1611676914795\",\"canvasLocation\":\"default\"} -->\n<!-- wp:image {\"id\":21931,\"sizeSlug\":\"large\",\"linkDestination\":\"media\",\"canvasClassName\":\"cnvs-block-core-image-1611676927286\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"https://wakilisha.africa/wp-content/uploads/2021/01/Black-and-white-portrait-of-young-African-woman-with-hat-made-of-roses-on-wakilisha.africa.jpg\"><img src=\"https://wakilisha.africa/wp-content/uploads/2021/01/Black-and-white-portrait-of-young-African-woman-with-hat-made-of-roses-on-wakilisha.africa-1160x653.jpg\" alt=\"\" class=\"wp-image-21931\"/></a></figure>\n<!-- /wp:image -->\n<!-- /wp:canvas/section-content -->\n<!-- /wp:canvas/section -->\n\n<!-- wp:columns {\"canvasClassName\":\"cnvs-block-core-columns-1611676970429\"} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"canvasClassName\":\"cnvs-block-core-column-1611676972078\"} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"canvasClassName\":\"cnvs-block-core-heading-1611676977814\"} -->\n<h3 class=\"has-text-align-center\">WHY WE EXIST</h3>\n<!-- /wp:heading --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"canvasClassName\":\"cnvs-block-core-columns-1611677156706\",\"marginLeft\":20,\"marginRight\":20} -->\n<div class=\"wp-block-columns cnvs-block-core-columns-1611677156706\"><!-- wp:column {\"width\":\"25%\",\"canvasClassName\":\"cnvs-block-core-column-1611677160647\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:25%\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\",\"canvasClassName\":\"cnvs-block-core-column-1611677160657\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:paragraph {\"canvasClassName\":\"cnvs-block-core-paragraph-1611677012985\",\"marginLeft\":20,\"marginRight\":20} -->\n<p class=\"cnvs-block-core-paragraph-1611677012985\">Intellectual capital is now the single most important asset owned by any organization. The continuity of a business largely depends on the innovation capacity of the business. The capacity of a business to continuously innovate is a huge factor to consider when determining the long-term sustainability of that business.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"canvasClassName\":\"cnvs-block-core-paragraph-1611677036019\",\"marginLeft\":20,\"marginRight\":20} -->\n<p class=\"cnvs-block-core-paragraph-1611677036019\">While society might not be a business, intellectual capital provides us with a versatile solution to many of the problems we face in today’s world. From tackling climate change, putting a stop to social inequalities and other societal injustices. WAKILISHA aim to expand the role of creative thinking in the society through the creation of culture content, partnerships with creative practitioners, social media engagement and digital curation.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"canvasClassName\":\"cnvs-block-core-paragraph-1611677036027\",\"marginLeft\":20,\"marginRight\":20} -->\n<p class=\"cnvs-block-core-paragraph-1611677036027\">— Culture<br>— Collaboration<br>— Curation</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"25%\",\"canvasClassName\":\"cnvs-block-core-column-1611677160667\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:25%\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:canvas/section {\"canvasClassName\":\"cnvs-block-section-1611677345681\",\"canvasLocation\":\"root\",\"layout\":\"full\"} -->\n<!-- wp:canvas/section-content {\"canvasClassName\":\"cnvs-block-section-content-1611677350787\",\"canvasLocation\":\"default\"} -->\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"canvasClassName\":\"cnvs-block-core-heading-1611677364193\"} -->\n<h3 class=\"has-text-align-center\">CULTURE</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"canvasClassName\":\"cnvs-block-core-paragraph-1611680883616\"} -->\n<p class=\"has-text-align-center\">Expressing your cultural identity is your right</p>\n<!-- /wp:paragraph -->\n<!-- /wp:canvas/section-content -->\n<!-- /wp:canvas/section -->\n\n<!-- wp:canvas/section {\"canvasClassName\":\"cnvs-block-section-1611679792507\",\"canvasLocation\":\"root\",\"layout\":\"full\"} -->\n<!-- wp:canvas/section-content {\"canvasClassName\":\"cnvs-block-section-content-1611679794420\",\"canvasLocation\":\"default\"} -->\n<!-- wp:columns {\"canvasClassName\":\"cnvs-block-core-columns-1611679798169\"} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":16.67,\"canvasClassName\":\"cnvs-block-core-column-1611679802593\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:16.67%\"><!-- wp:image {\"id\":21212,\"sizeSlug\":\"large\",\"linkDestination\":\"media\",\"className\":\"is-style-default\",\"canvasClassName\":\"cnvs-block-core-image-1611681245043\"} -->\n<figure class=\"wp-block-image size-large is-style-default\"><a href=\"https://wakilisha.africa/wp-content/uploads/2020/12/wakilisha-creative-enterprise-culture.jpg\"><img src=\"https://wakilisha.africa/wp-content/uploads/2020/12/wakilisha-creative-enterprise-culture-1160x653.jpg\" alt=\"\" class=\"wp-image-21212\"/></a></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":41.67,\"canvasClassName\":\"cnvs-block-core-column-1611679802611\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:41.67%\"><!-- wp:image {\"id\":20193,\"sizeSlug\":\"large\",\"linkDestination\":\"media\",\"canvasClassName\":\"cnvs-block-core-image-1611679808286\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"https://wakilisha.africa/wp-content/uploads/2020/11/wakilisha-creative-enterprise-our-business-is-people.jpg\"><img src=\"https://wakilisha.africa/wp-content/uploads/2020/11/wakilisha-creative-enterprise-our-business-is-people-1160x653.jpg\" alt=\"\" class=\"wp-image-20193\"/></a></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":25,\"canvasClassName\":\"cnvs-block-core-column-1611680982020\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:25%\"><!-- wp:image {\"id\":20344,\"sizeSlug\":\"large\",\"linkDestination\":\"media\",\"className\":\"is-style-default\",\"canvasClassName\":\"cnvs-block-core-image-1611681151326\"} -->\n<figure class=\"wp-block-image size-large is-style-default\"><a href=\"https://wakilisha.africa/wp-content/uploads/2020/11/wakilisha-creative-enterprise-stylish-young-african-woman-design-inspiration.jpg\"><img src=\"https://wakilisha.africa/wp-content/uploads/2020/11/wakilisha-creative-enterprise-stylish-young-african-woman-design-inspiration-1160x653.jpg\" alt=\"\" class=\"wp-image-20344\"/></a></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":16.67,\"canvasClassName\":\"cnvs-block-core-column-1611679802634\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:16.67%\"><!-- wp:image {\"id\":20795,\"sizeSlug\":\"large\",\"linkDestination\":\"media\",\"className\":\"is-style-default\",\"canvasClassName\":\"cnvs-block-core-image-1611681262273\"} -->\n<figure class=\"wp-block-image size-large is-style-default\"><a href=\"https://wakilisha.africa/wp-content/uploads/2020/12/wakilisha-creative-enterprise-visual-trends-for-2021-unfiltered-access.jpg\"><img src=\"https://wakilisha.africa/wp-content/uploads/2020/12/wakilisha-creative-enterprise-visual-trends-for-2021-unfiltered-access-1160x653.jpg\" alt=\"wakilisha-creative-enterprise-visual-trends-for-2021-unfiltered-access\" class=\"wp-image-20795\"/></a></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n<!-- /wp:canvas/section-content -->\n<!-- /wp:canvas/section -->\n\n<!-- wp:columns {\"canvasClassName\":\"cnvs-block-core-columns-1611677493931\",\"marginLeft\":20,\"marginRight\":20} -->\n<div class=\"wp-block-columns cnvs-block-core-columns-1611677493931\"><!-- wp:column {\"width\":\"25%\",\"canvasClassName\":\"cnvs-block-core-column-1611677505964\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:25%\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\",\"canvasClassName\":\"cnvs-block-core-column-1611677505977\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:paragraph {\"canvasClassName\":\"cnvs-block-core-paragraph-1611680844134\",\"marginLeft\":20,\"marginRight\":20} -->\n<p class=\"cnvs-block-core-paragraph-1611680844134\">We believe in everyone’s freedom to express their cultural heritage. We are strong advocates for your right to tell your story and to transmit it, whoever you are. WAKILISHA works with artists, cultural communities, and many other organizations to nurture the diversity of cultural expression.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"canvasClassName\":\"cnvs-block-core-paragraph-1611677707662\",\"marginLeft\":20,\"marginRight\":20} -->\n<p class=\"cnvs-block-core-paragraph-1611677707662\">Our work involves the production of cultural goods, services and intellectual works that can be accessed as literature, music, visual arts, live performances or even cinematography.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"25%\",\"canvasClassName\":\"cnvs-block-core-column-1611677506000\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:25%\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"canvasClassName\":\"cnvs-block-core-spacer-1611681980530\"} -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"canvasClassName\":\"cnvs-block-core-columns-1611678911538\"} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"25%\",\"canvasClassName\":\"cnvs-block-core-column-1611678913517\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:25%\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\",\"canvasClassName\":\"cnvs-block-core-column-1611678913542\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"canvasClassName\":\"cnvs-block-core-heading-1611678917301\"} -->\n<h3 class=\"has-text-align-center\">COLLABORATION</h3>\n<!-- /wp:heading --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"25%\",\"canvasClassName\":\"cnvs-block-core-column-1611678913557\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:25%\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"canvasClassName\":\"cnvs-block-core-paragraph-1611681679757\"} -->\n<p class=\"has-text-align-center\">Collaboration promotes the circulation of ideas</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"canvasClassName\":\"cnvs-block-core-columns-1611681379415\"} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"25%\",\"canvasClassName\":\"cnvs-block-core-column-1611681381670\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:25%\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\",\"canvasClassName\":\"cnvs-block-core-column-1611681381694\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:image {\"id\":21213,\"sizeSlug\":\"large\",\"linkDestination\":\"media\",\"className\":\"is-style-default\",\"canvasClassName\":\"cnvs-block-core-image-1611681384255\",\"marginLeft\":20,\"marginRight\":20} -->\n<figure class=\"wp-block-image size-large is-style-default cnvs-block-core-image-1611681384255\"><a href=\"https://wakilisha.africa/wp-content/uploads/2020/12/wakilisha-creative-enterprise-collaboration.jpg\"><img src=\"https://wakilisha.africa/wp-content/uploads/2020/12/wakilisha-creative-enterprise-collaboration-1160x653.jpg\" alt=\"\" class=\"wp-image-21213\"/></a></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"25%\",\"canvasClassName\":\"cnvs-block-core-column-1611681381721\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:25%\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:canvas/section {\"canvasClassName\":\"cnvs-block-section-1611679365866\",\"canvasLocation\":\"root\",\"marginLeft\":20,\"marginRight\":20,\"layout\":\"full\"} -->\n<!-- wp:canvas/section-content {\"canvasClassName\":\"cnvs-block-section-content-1611679367909\",\"canvasLocation\":\"default\"} -->\n<!-- wp:columns {\"canvasClassName\":\"cnvs-block-core-columns-1611679371321\"} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"canvasClassName\":\"cnvs-block-core-column-1611679377853\"} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":4,\"canvasClassName\":\"cnvs-block-core-heading-1611679390462\"} -->\n<h4><strong>Creative Partnerships</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"canvasClassName\":\"cnvs-block-core-paragraph-1611679390484\"} -->\n<p>Creative partnerships are essential in coming up with innovative solutions. We build relationships between creative practitioners, communities and organizations to foster innovation and improve people''s lives through the presentation and accumulation of diverse thoughts and ideas. Our partnerships work across and beyond the industry to connect those who can think of solutions with those in need of solutions</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"canvasClassName\":\"cnvs-block-core-column-1611679377870\"} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":4,\"canvasClassName\":\"cnvs-block-core-heading-1611679405642\"} -->\n<h4>Process Knowledge Sharing</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"canvasClassName\":\"cnvs-block-core-paragraph-1611679405663\"} -->\n<p>Process knowledge in cultural expression is an important skill. It empowers creatives to adopt existing ideas and turn them into new innovations for the modern age. WAKILISHA connects you with artists, designers and creative practitioners from all over the world as they invite you into their worlds, talking about their lives, design processes, industry knowledge and much more.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"canvasClassName\":\"cnvs-block-core-column-1611679377892\"} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":4,\"canvasClassName\":\"cnvs-block-core-heading-1611679420798\"} -->\n<h4>Social Media Engagement</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"canvasClassName\":\"cnvs-block-core-paragraph-1611679420813\"} -->\n<p>Due to it''s implicit nature, knowledge is hard to capture and manage. The rise of social media platforms and technologies has improved knowledge sharing and collaboration across the world. WAKILISHA uses Web 2.0 technologies like Facebook and Twitter to support knowledge sharing practices and to convert knowledge into its different forms for curation purposes.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n<!-- /wp:canvas/section-content -->\n<!-- /wp:canvas/section -->\n\n<!-- wp:spacer {\"canvasClassName\":\"cnvs-block-core-spacer-1611681990466\"} -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:canvas/section {\"canvasClassName\":\"cnvs-block-section-1611680585951\",\"canvasLocation\":\"root\",\"layout\":\"full\"} -->\n<!-- wp:canvas/section-content {\"canvasClassName\":\"cnvs-block-section-content-1611680587426\",\"canvasLocation\":\"default\"} -->\n<!-- wp:columns {\"canvasClassName\":\"cnvs-block-core-columns-1611680590299\"} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"canvasClassName\":\"cnvs-block-core-column-1611680592273\"} -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"canvasClassName\":\"cnvs-block-core-column-1611680592308\"} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"canvasClassName\":\"cnvs-block-core-heading-1611680597603\"} -->\n<h3 class=\"has-text-align-center\">CURATION</h3>\n<!-- /wp:heading --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"canvasClassName\":\"cnvs-block-core-column-1611680592327\"} -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"canvasClassName\":\"cnvs-block-core-paragraph-1611681930483\"} -->\n<p class=\"has-text-align-center\">Knowledge transmission is important for the development of society</p>\n<!-- /wp:paragraph -->\n<!-- /wp:canvas/section-content -->\n<!-- /wp:canvas/section -->\n\n<!-- wp:columns {\"canvasClassName\":\"cnvs-block-core-columns-1611681513155\"} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"25%\",\"canvasClassName\":\"cnvs-block-core-column-1611681515066\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:25%\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\",\"canvasClassName\":\"cnvs-block-core-column-1611681515112\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:image {\"id\":20158,\"sizeSlug\":\"large\",\"linkDestination\":\"media\",\"className\":\"is-style-default\",\"canvasClassName\":\"cnvs-block-core-image-1611681517901\",\"marginLeft\":20,\"marginRight\":20} -->\n<figure class=\"wp-block-image size-large is-style-default cnvs-block-core-image-1611681517901\"><a href=\"https://wakilisha.africa/wp-content/uploads/2020/11/digital-curation.jpg\"><img src=\"https://wakilisha.africa/wp-content/uploads/2020/11/digital-curation-1160x653.jpg\" alt=\"\" class=\"wp-image-20158\"/></a></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"25%\",\"canvasClassName\":\"cnvs-block-core-column-1611681515140\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:25%\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:canvas/section {\"canvasClassName\":\"cnvs-block-section-1611680637795\",\"canvasLocation\":\"root\",\"layout\":\"full\"} -->\n<!-- wp:canvas/section-content {\"canvasClassName\":\"cnvs-block-section-content-1611680644440\",\"canvasLocation\":\"default\"} -->\n<!-- wp:columns {\"canvasClassName\":\"cnvs-block-core-columns-1611680646705\"} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"25%\",\"canvasClassName\":\"cnvs-block-core-column-1611680649292\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:25%\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\",\"canvasClassName\":\"cnvs-block-core-column-1611680649322\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:paragraph {\"canvasClassName\":\"cnvs-block-core-paragraph-1611680656745\"} -->\n<p><br>90 percent of the information produced in the world was created within the last year. This rate of creation will only accelerate with improving internet speeds and widening smartphone accessibility. The need for curation has never been more urgent¹. WAKILISHA records, archives and curates cultural content and other information through the help of technology-enabled means. We do this to preserve knowledge for future generations and to provide others on this journey with a somewhat clear communication line to the 21st century society.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"canvasClassName\":\"cnvs-block-core-paragraph-1611680656798\"} -->\n<p>¹<a href=\"https://www.economist.com/open-future/2019/02/21/we-must-fight-to-preserve-digital-information\">Preserving the Digital Economy</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"25%\",\"canvasClassName\":\"cnvs-block-core-column-1611680649343\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:25%\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n<!-- /wp:canvas/section-content -->\n<!-- /wp:canvas/section -->\n\n<!-- wp:paragraph {\"canvasClassName\":\"cnvs-block-core-paragraph-1611677532357\"} -->\n<p></p>\n<!-- /wp:paragraph -->","excerpt_html":"null","editable_payload":"{\"spay_email\":\"\"}","immutable_payload":"{\"psp_kw\":\"\",\"wpGuid\":\"http://18.135.76.250/?page_id=21928\",\"metaHash\":\"ce7c027ffbd7a7fd9f026866efb21b9934bd72ae28825e38aa99aa4e249a5ab6\",\"psp_meta\":\"a:17:{s:5:\\\"title\\\";s:0:\\\"\\\";s:11:\\\"description\\\";s:295:\\\"We believe in everyone’s freedom to express their cultural heritage. We are strong advocates for your right to tell your story and to transmit it, whoever you are. WAKILISHA works with artists, cultural communities, and many other organizations to nurture the diversity of cultural expression.\\\";s:8:\\\"keywords\\\";s:0:\\\"\\\";s:13:\\\"focus_keyword\\\";s:0:\\\"\\\";s:14:\\\"mfocus_keyword\\\";s:0:\\\"\\\";s:17:\\\"facebook_isactive\\\";s:0:\\\"\\\";s:14:\\\"facebook_titlu\\\";s:0:\\\"\\\";s:13:\\\"facebook_desc\\\";s:0:\\\"\\\";s:14:\\\"facebook_image\\\";s:0:\\\"\\\";s:23:\\\"facebook_opengraph_type\\\";s:0:\\\"\\\";s:12:\\\"robots_index\\\";s:0:\\\"\\\";s:13:\\\"robots_follow\\\";s:0:\\\"\\\";s:8:\\\"priority\\\";s:0:\\\"\\\";s:9:\\\"canonical\\\";s:0:\\\"\\\";s:21:\\\"psp_twc_post_cardtype\\\";s:4:\\\"none\\\";s:20:\\\"psp_twc_app_isactive\\\";s:2:\\\"no\\\";s:22:\\\"psp_twc_post_thumbsize\\\";s:4:\\\"none\\\";}\",\"psp_score\":35,\"termsHash\":\"4f53cda18c2baa0c0354bb5f9a3ecbe5ed12ab4d8e11b